def main():
    print(f"NEET Topics Count: {len(NEET_TOPICS)}")
    print(f"MRCP Topics Count: {len(MRCP_TOPICS)}")
    print(f"FCPS Topics Count: {len(FCPS_TOPICS)}")

    assert len(NEET_TOPICS) == 100
    assert len(MRCP_TOPICS) == 100
    assert len(FCPS_TOPICS) == 100

    for name, lst in [("NEET", NEET_TOPICS), ("MRCP", MRCP_TOPICS), ("FCPS", FCPS_TOPICS)]:
        for i, t in enumerate(lst):
            assert t[1] in TAXONOMY_SUBJECTS, f"Invalid subject {t[1]} at {name} #{i}: {t[0]}"
            assert t[2] in TAXONOMY_SYSTEMS, f"Invalid system {t[2]} at {name} #{i}: {t[0]}"
            assert t[5].startswith("https://"), f"Invalid URL at {name} #{i}: {t[5]}"

    out_path = os.path.join(os.path.dirname(__file__), "mega116_topics.py")
    with open(out_path, "w", encoding="utf-8") as f:
        f.write("# Auto-generated Mega-Batch 116 topics (NEET 100, MRCP 100, FCPS 100)\n\n")
        f.write(f"NEET_TOPICS = {json.dumps(NEET_TOPICS, indent=2)}\n\n")
        f.write(f"MRCP_TOPICS = {json.dumps(MRCP_TOPICS, indent=2)}\n\n")
        f.write(f"FCPS_TOPICS = {json.dumps(FCPS_TOPICS, indent=2)}\n")

    print(f"Saved Mega-Batch 116 topics to {out_path}!")

if __name__ == "__main__":
    main()
